<script setup lang="ts">
import {computed,nextTick,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {useResearchStore} from '../stores/research'
import {useBackendStore,errorText} from '../stores/backend'
import {backendApi,BackendApiError,type BackendConversation,type BackendMessage} from '../services/backendApi'
import {contextPrompt,type ComposerReference} from '../lib/composerContext'
import {textBlocks,nearbyPreview,incompleteSelection,retrieveEvidence,readingInstruction,validateReadingScope,type EvidenceBlock,type ReaderComposerBridge,type ReadingRequest} from '../lib/readerContext'
import type {LocalDocument} from '../types'
import Composer from './ResearchComposer.vue'
import Messages from './BackendConversation.vue'
import Menu from './ConversationMenu.vue'
import Icon from './AppIcon.vue'
const props=defineProps<{workspaceId:string;doc:LocalDocument;page:number;pages:{page:number;text:string}[];selection:{quote:string;rects:number[][];page:number}|null;request:{id:number;operation:string}|null}>()
const emit=defineEmits<{locate:[value:ReadingRequest];save:[value:{message:BackendMessage;source:ReadingRequest;conversationId:string;question:string}];question:[text:string]}>()
const backend=useBackendStore(),research=useResearchStore(),composer=ref<InstanceType<typeof Composer>>(),scroll=ref<HTMLElement>()
const replacement=ref<{block:EvidenceBlock;operation:string}|null>(null)
const baseSelection=ref<EvidenceBlock|null>(null),allowed=ref<EvidenceBlock[]>([]),preview=ref<EvidenceBlock|null>(null),pending=ref<{block:EvidenceBlock;operation:string}|null>(null),mode=ref<'overview'|'study'|'critical'>('study'),error=ref(''),ready=ref(false),historyOpen=ref(false),history=ref<BackendConversation[]>([]),historyState=ref('active'),editing=ref<BackendConversation>(),title=ref(''),deleting=ref<BackendConversation>(),saving=ref(false)
const workspace=props.workspaceId,channel='reader:'+props.doc.hash,blocks=computed(()=>props.pages.flatMap(p=>textBlocks(p.page-1,p.text))),paper=computed(()=>research.papers.find(p=>p.localDocumentId===props.doc.id&&research.sessions.find(s=>s.id===props.workspaceId)?.paperIds.includes(p.id))),label=computed(()=>paper.value?.title||props.doc.name)
let disposed=false,sessionReady:Promise<void>|undefined,booting:Promise<void>|undefined
const eligibleNotes=computed(()=>props.doc.annotations.filter(n=>n.workspaceId===workspace&&(!n.ownerId||n.ownerId===backend.user?.id)))
const current=()=>!disposed&&backend.channel===channel&&backend.spaceId===workspace
const scope=()=>({documentId:props.doc.id,documentVersion:props.doc.hash,evidence:allowed.value})
async function list(){if(!backend.user)return;const data=await backendApi.readingConversations(workspace,props.doc.id,props.doc.hash,historyState.value);if(current())history.value=data.items}
function refreshHistory(){void list().catch(e=>{if(current())error.value=errorText(e)})}
async function bind(){if(!current())throw new Error('阅读文档已改变，请在当前页面重试。');const id=await backend.ensureConversation();await backendApi.bindReading(id,{documentId:props.doc.id,documentVersion:props.doc.hash,initialPage:props.page});if(!current()||backend.conversationId!==id)throw new Error('阅读会话已改变。')}
async function fresh(){if(backend.busy)throw new Error('请先停止当前生成。');await backend.newConversation();await bind();allowed.value=[];pending.value=null;replacement.value=null;await list()}
function boot(){if(booting)return booting;booting=initialize().finally(()=>booting=undefined);return booting}
async function initialize(){try{ready.value=false;await backend.init();if(disposed)return;if(!backend.user){error.value='登录并配置模型后可开始连续阅读对话。';return}await backend.switchWorkspace(workspace);if(disposed)return;await backend.switchChannel(channel);if(disposed)return;await list();if(!current())return;if(backend.conversationId&&!history.value.some(c=>c.id===backend.conversationId)){await backend.newConversation()}if(!backend.conversationId)await backend.newConversation();await bind();if(current()){ready.value=true;error.value=''}}catch(e){if(!disposed)error.value=e instanceof BackendApiError&&e.status===404?'阅读会话接口尚未可用，请重启 Spring Boot 后端以应用本次升级。':errorText(e)}}
onMounted(()=>{sessionReady=boot()})
watch(()=>backend.user?.id,()=>{if(!disposed&&backend.user&&!ready.value)sessionReady=boot()})
onBeforeUnmount(()=>{disposed=true;if(backend.channel===channel)void backend.switchChannel('chat').catch(()=>{})})
function selectedBlock(){const s=props.selection;if(!s||!s.quote.trim()||s.quote==='区域批注')throw new Error('请选择可复制的原文文字。当前模型网关仅支持文本，区域图片不会发送。');if(s.quote.length>4000)throw new Error('请缩小选区至4000字以内。');return{chunkId:'selection-'+s.page,pageIndex:s.page-1,quote:s.quote,rects:s.rects.map(r=>[...r]),scope:'selection' as const}}
function reference(){prepare('ask')}
const operationText:Record<string,string>={explain:'请解释这段原文。',translate:'请翻译所选原文并保留技术术语。',formula:'请逐步解释这段公式中的符号、矩阵维度和设计动机，并区分教学示例与论文事实。',table:'请分析所选表格的实验对象、基线、指标方向、数据支持的结论及其边界。'}
function runOperation(block:EvidenceBlock,operation:string,confirmed=false){if(!confirmed&&allowed.value.length&&JSON.stringify(allowed.value)!==JSON.stringify([block])){replacement.value={block,operation};return}replacement.value=null;if(block.scope==='selection')baseSelection.value=block;allowed.value=[block];pending.value=null;preview.value=null;if(operation==='ask')void nextTick(()=>composer.value?.focus());else void nextTick(()=>composer.value?.submit(operationText[operation]||operationText.explain!))}
function previewNearby(){const block=allowed.value[0];if(!block||block.scope!=='selection')return;pending.value={block,operation:'ask'};preview.value=nearbyPreview(blocks.value,block.pageIndex,block.quote)}
function prepare(operation:string){error.value='';try{const block=selectedBlock();if(operation!=='ask'&&incompleteSelection(block.quote)){pending.value={block,operation};preview.value=nearbyPreview(blocks.value,block.pageIndex,block.quote);return}runOperation(block,operation)}catch(e){error.value=errorText(e)}}
watch(()=>props.selection,()=>{error.value='';pending.value=null;preview.value=null})
watch(()=>props.request,request=>{if(request)prepare(request.operation)},{flush:'post'})
async function send(input:Parameters<ReaderComposerBridge['send']>[0]){
 const authorized=validateReadingScope(input.readingContext,props.doc.id,props.doc.hash).evidence.map(e=>({...e,rects:e.rects.map(r=>[...r])}))
 if(sessionReady)await sessionReady;if(!ready.value){sessionReady=boot();await sessionReady}if(!ready.value||!current())throw new Error(error.value||'阅读会话尚未就绪。');await bind()
 const manual=input.skillId;let skill=manual||'chat';if(!['chat','paper_read'].includes(skill)&&!backend.runnableSkills.some(s=>s.id===skill))throw new Error('该任务暂不支持在阅读对话直接执行；请使用当前注册的科研 Skill。')
 if(input.references.some(r=>r.kind==='document'))throw new Error('本阅读对话仅接受明确选区或文本块；请先在 PDF 中选择要引用的原文。')
 const noteSources=input.references.filter(r=>r.kind==='note').map(r=>{const note=eligibleNotes.value.find(n=>n.id===r.id);if(!note)throw new Error('笔记不属于当前文档。');return{id:note.id,kind:'note',name:'阅读笔记',scope:'用户保存的理解，不等于原文证据',body:note.comment.slice(0,1500)}})
 const evidence=retrieveEvidence(authorized,input.text),reading={documentId:props.doc.id,documentVersion:props.doc.hash,evidence}
 const sources=[{id:paper.value?.id||props.doc.id,kind:'paper',name:label.value,scope:'用户提供的题录元数据；不代表已读全文',body:JSON.stringify({title:label.value,authors:paper.value?.authors,year:paper.value?.year,summary:paper.value?.summary?.slice(0,500)})},...evidence.map(e=>({id:e.chunkId,kind:'excerpt',name:'PDF 第 '+(e.pageIndex+1)+' 页',versionId:props.doc.hash,scope:e.scope==='selection'?'用户明确选区，浏览器文本层；未服务端复核':'用户确认的邻近文本块，非可靠语义段落；未服务端复核'})),...noteSources]
 const question=input.text.trim()||operationText.explain!,prompt=contextPrompt(question,{taskInstructions:readingInstruction(mode.value,question),version:1,skill,skillName:backend.skills.find(s=>s.id===skill)?.name||'阅读对话',sources})
 const accepted=await backend.send(prompt,{skillId:skill,documentIds:[],readingContext:reading,reasoningEffort:input.reasoningEffort,responseStyle:input.responseStyle});if(current()&&accepted)refreshHistory();return accepted
}
const bridge=computed<ReaderComposerBridge>(()=>({key:workspace+':reader:'+props.doc.hash,mentions:[{id:paper.value?.id||props.doc.id,kind:'paper',name:label.value,description:'当前论文题录；不代表授权全文'},...eligibleNotes.value.map(n=>({id:n.id,kind:'note' as const,name:n.comment.slice(0,40)||n.quote.slice(0,40)||'阅读笔记',description:'用户保存的阅读内容'}))],referenceSelection:reference,citation:{title:label.value,source:scope()},removeCitation:()=>{allowed.value=[];replacement.value=null;pending.value=null;preview.value=null},locateCitation:s=>emit('locate',s),restoreCitation:s=>{if(s.documentId===props.doc.id&&s.documentVersion===props.doc.hash)allowed.value=s.evidence.map(e=>({...e,rects:e.rects.map(r=>[...r])}))},send,fresh}))
async function open(c:BackendConversation){try{if(!current())return;if(backend.busy)throw new Error('请先停止当前生成。');await backend.openConversation(c.id);allowed.value=[];pending.value=null;replacement.value=null;historyOpen.value=false}catch(e){error.value=errorText(e)}}
async function manage(c:BackendConversation,action:string){try{if(action==='rename'){editing.value=c;title.value=c.title;return}if(action==='delete'){deleting.value=c;return}await backend.manageConversation(c,action);if(!current())return;if(!backend.conversationId)await fresh();await list()}catch(e){error.value=errorText(e)}}
async function rename(){if(!editing.value||!title.value.trim())return;try{await backendApi.renameConversation(editing.value.id,title.value,editing.value.revision);editing.value=undefined;await list()}catch(e){error.value=errorText(e)}}
async function remove(){if(!deleting.value)return;try{await backend.manageConversation(deleting.value,'delete');if(!current())return;deleting.value=undefined;if(!backend.conversationId)await fresh();await list()}catch(e){error.value=errorText(e)}}
async function save(message:BackendMessage){
 if(saving.value||!current())return;saving.value=true;const conversationId=backend.conversationId;
 try{const stored=await backendApi.conversation(conversationId),original=stored.messages.find(m=>m.runId===message.runId&&m.role==='user'),completed=stored.messages.find(m=>m.runId===message.runId&&m.role==='assistant'),reading=original?.execution?.reading;
  if(!completed?.content||!reading||reading.documentId!==props.doc.id||reading.documentVersion!==props.doc.hash)throw new Error('回答或来源快照尚未就绪，请稍后重试。');
  const question=original!.content.split('\n\n')[0]||'';await backendApi.saveNote(conversationId,{title:'论文理解 · '+label.value.slice(0,50),body:completed.content+'\n\n原始提问：'+question+'\n来源快照：'+JSON.stringify(reading)},'reader-note-'+message.runId);
  if(current())emit('save',{message:completed,source:reading,conversationId,question});research.notify('AI 理解及来源已保存到笔记。')
 }catch(e){if(current())error.value=errorText(e)}finally{saving.value=false}
}
function bottom(){const el=scroll.value;if(el&&el.scrollHeight-el.scrollTop-el.clientHeight<100)void nextTick(()=>{if(scroll.value)scroll.value.scrollTop=scroll.value.scrollHeight})}
watch(()=>backend.messages.at(-1)?.content,bottom,{flush:'pre'})
function sent(){void nextTick(()=>{if(scroll.value)scroll.value.scrollTop=scroll.value.scrollHeight})}
function noteRequest(){emit('question','尚未解决的问题：')}
async function openLinkedConversation(id:string){try{const data=await backendApi.readingConversations(workspace,props.doc.id,props.doc.hash);if(!current())return;const c=data.items.find(c=>c.id===id);if(!c){error.value='原阅读对话已不可用或已归档，可在历史中检查；独立笔记内容仍保留。';return}await open(c)}catch(e){error.value=errorText(e)}}
defineExpose({openLinkedConversation,prepare,focus:()=>composer.value?.focus()})
</script>
<template><section class="reader-conversation" aria-label="Orbit AI 阅读助手"><header class="reader-conversation-header"><strong><Icon name="Sparkles" :size="16"/>Orbit AI</strong><div><button class="icon-button" aria-label="本篇阅读对话历史" @click="historyOpen=!historyOpen;refreshHistory()"><Icon name="MessageSquare" :size="16"/></button><button class="icon-button" aria-label="新建阅读对话" :disabled="backend.busy||!ready" @click="fresh().catch(e=>error=errorText(e))"><Icon name="Plus" :size="16"/></button></div></header>
<div class="reader-context"><strong>{{label}}</strong><div><span>PDF 第 {{page}} 页</span><select v-model="mode" aria-label="阅读解释模式"><option value="overview">快速概览</option><option value="study">研究生精读</option><option value="critical">批判性分析</option></select></div><small>{{allowed.length?'本轮引用 '+allowed.reduce((n,b)=>n+b.quote.length,0)+' 字；只发送明确片段':'当前未引用原文；自由提问使用题录、已授权历史及模型知识'}}</small><details class="reader-context-actions"><summary>引用与阅读操作</summary><button v-if="allowed[0]?.scope==='selection'" class="text-button" @click="previewNearby">预览邻近文本</button><button v-if="allowed[0]?.scope==='nearby'&&baseSelection" class="text-button" @click="allowed=[baseSelection!]">仅用原选区</button><small v-if="allowed.length">移除不会撤回已发送的历史内容。</small><button class="text-button" :disabled="!selection" @click="reference">引用当前选区</button><button class="text-button" @click="noteRequest">记录未解问题</button></details></div>
<div v-if="historyOpen" class="reader-history"><label>本篇对话<select v-model="historyState" @change="refreshHistory"><option value="active">进行中</option><option value="archived">已归档</option></select></label><p v-if="!history.length">暂无本篇阅读对话。</p><div v-for="c in history" :key="c.id"><button class="text-button" :disabled="backend.busy||historyState==='archived'" @click="open(c)">{{c.title}}</button><Menu :title="'管理阅读对话 '+c.title" :items="[{id:'rename',label:'重命名'},{id:c.archivedAt?'unarchive':'archive',label:c.archivedAt?'取消归档':'归档'},{id:'delete',label:'移至最近删除'}]" @select="manage(c,$event)"/></div><form v-if="editing" @submit.prevent="rename"><label>阅读对话名称<input v-model="title" maxlength="180"/></label><button class="text-button">保存名称</button></form><div v-if="deleting"><p>将此对话移至最近删除？已保存笔记会保留。</p><button class="text-button" @click="deleting=undefined">取消</button><button class="text-button" @click="remove">确认移至最近删除</button></div></div>
<div v-if="replacement" class="reader-expansion" role="region" aria-label="确认替换原文引用"><p>已有待发送原文。是否替换为新选区？输入的问题会保留。</p><blockquote>{{replacement.block.quote}}</blockquote><button type="button" class="text-button" @click="runOperation(replacement!.block,replacement!.operation,true)">替换原文引用</button><button type="button" class="text-button" @click="replacement=null">保留原引用</button></div>
<div v-if="pending" class="reader-expansion" role="region" aria-label="选区补充授权"><p>{{incompleteSelection(pending.block.quote)?'选区可能在句中截断。':'可以补充邻近文本。'}}只在你确认后扩大引用范围。</p><details v-if="preview"><summary>预览邻近文本（自动文本块，不保证完整段落）</summary><blockquote>{{preview.quote}}</blockquote></details><p v-else>无法可靠定位邻近内容，请调整选区。不会猜补原文。</p><button class="text-button" @click="runOperation(pending.block,pending.operation)">{{pending.operation==='ask'?'保持仅选区':'仅解释选区'}}</button><button v-if="preview" class="text-button" @click="runOperation(preview!,pending!.operation)">授权补充预览文本</button><button class="text-button" @click="pending=null;preview=null">取消</button></div>
<p v-if="error" class="form-error" role="alert">{{error}}</p><div ref="scroll" class="reader-chat-scroll"><p v-if="!backend.messages.length" class="settings-hint">直接提问，或选中原文后加入对话。不会自动发送整份 PDF。</p><Messages v-if="current()" reading @locate="emit('locate',$event)" @save="save"/></div><Composer ref="composer" :notes="[]" :reader="bridge" @sent="sent" @history="historyOpen=true;refreshHistory()" @fresh="allowed=[]"/>
</section></template>
<style scoped>.reader-conversation{display:flex;flex-direction:column;min-height:0;flex:1;overflow:hidden}.reader-conversation-header{display:flex;align-items:center;justify-content:space-between;padding:12px 16px;border-bottom:1px solid var(--border)}.reader-conversation-header strong{display:flex;gap:7px;align-items:center;font-size:14px}.reader-conversation-header>div{display:flex}.reader-context{padding:10px 16px;flex:none;border-bottom:1px solid var(--border);max-height:25dvh;overflow:auto}.reader-context strong{display:block;font-size:12px;line-height:1.5;overflow-wrap:anywhere}.reader-context>div{display:flex;gap:8px;align-items:center;margin:6px 0}.reader-context small{display:block;font-size:11px;color:var(--muted);line-height:1.6}.reader-context select,.reader-history select{font-size:11px;background:var(--surface);border:1px solid var(--border);border-radius:5px;padding:4px}.reader-context span{font-size:11px}.reader-context summary,.reader-expansion summary{font-size:12px;cursor:pointer;margin:6px 0}.reader-context blockquote,.reader-expansion blockquote{white-space:pre-wrap;font-size:12px;line-height:1.6;max-height:150px;overflow:auto;margin:8px 0}.reader-chat-scroll{flex:1;min-height:80px;overflow:auto;padding:14px;scrollbar-width:thin;scrollbar-color:var(--border-light) transparent;overscroll-behavior:contain}.reader-history,.reader-expansion{padding:10px 14px;max-height:30dvh;overflow:auto;background:var(--surface);border-bottom:1px solid var(--border);font-size:12px}.reader-history>div{display:flex;justify-content:space-between}.reader-history>div>button{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:85%}.reader-expansion>button{font-size:12px}.reader-conversation>.form-error{padding:0 14px}.reader-conversation :deep(.research-composer-wrap){flex:none;padding:10px}.reader-conversation :deep(.assistant-compose){margin:0}.reader-conversation :deep(.composer-model-button){min-width:0}.reader-conversation :deep(.composer-model-button>span){max-width:100px}.reader-conversation :deep(.compose-toolbar){gap:3px;flex-wrap:wrap}</style>
